def recolor_hidden_copies(grid, acc, shape):
    """Recolor to acc every 0-cell covered by a placement of shape lying entirely on 0-cells."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    hits = set()
    for i in range(h):
        for j in range(w):
